t.script:
(function () {
  "use strict";

  function $(sel, root){return (root||document).querySelector(sel);}
  function qa(sel, root){return Array.from((root||document).querySelectorAll(sel));}
  function $val(id, d){ var el=$("#"+id); return el?el.value:d; }

  async function loadImage(src){
    return new Promise(function(resolve, reject){
      var im=new Image();
      im.onload=function(){ resolve(im); };
      im.onerror=function(e){ reject(e); };
      im.src=src;
    });
  }
  function readAsDataURL(file){
    return new Promise(function(resolve, reject){
      var r=new FileReader();
      r.onload=function(){ resolve(r.result); };
      r.onerror=reject;
      r.readAsDataURL(file);
    });
  }

  var S={ logoDataURL:"", isSVG:false };

  function applyTransform(){
    var logo = $("#spw_logo_preview"); if(!logo) return;
    var base = $("#spw_product_img");  if(!base) return;

    var sizePx = parseInt($val("spw_size","100"),10);
    var posX   = parseInt($val("spw_pos_x","0"),10);
    var posY   = parseInt($val("spw_pos_y","10"),10);
    var rot    = parseInt($val("spw_rotation","0"),10);

    var bw = base.clientWidth, bh = base.clientHeight;
    var leftPx = bw*(0.5 + posX/100);
    var topPx  = bh*(0.6 + posY/100);

    logo.style.position="absolute";
    logo.style.left = leftPx + "px";
    logo.style.top  = topPx  + "px";
    logo.style.transform = "translate(-50%, -50%) rotate("+rot+"deg)";
    logo.style.width = sizePx + "px";
    logo.classList.remove("d-none");
    logo.style.opacity = "1";
  }

  async function renderPNGDataURL(){
    var internalBaseEl = $("#spw-base-img");
    var baseSrc = (internalBaseEl && internalBaseEl.getAttribute("src")) ||
                  $val("spw_img_src","") ||
                  ($("#spw_product_img")||{}).getAttribute("src");
    if(!baseSrc) throw new Error("Sin imagen base.");

    var baseIm = await loadImage(baseSrc);

    var canvas = document.createElement("canvas");
    var ctx = canvas.getContext("2d");
    canvas.width  = baseIm.naturalWidth  || baseIm.width;
    canvas.height = baseIm.naturalHeight || baseIm.height;

    ctx.drawImage(baseIm, 0, 0, canvas.width, canvas.height);

    var logoEl = $("#spw_logo_preview");
    if(logoEl && logoEl.src){
      var baseEl = $("#spw_product_img");
      var bw = baseEl.clientWidth,  bh = baseEl.clientHeight;
      var br = baseEl.getBoundingClientRect();
      var lr = logoEl.getBoundingClientRect();

      var cx_norm = ((lr.left + lr.width/2)  - br.left) / bw;
      var cy_norm = ((lr.top  + lr.height/2) - br.top ) / bh;
      var w_norm  = lr.width / bw;

      var cx = cx_norm * canvas.width;
      var cy = cy_norm * canvas.height;
      var drawW = w_norm * canvas.width;

      var logoIm = await loadImage(logoEl.src);
      var ratio = (logoIm.naturalHeight || logoIm.height) / (logoIm.naturalWidth || logoIm.width);
      var drawH = drawW * ratio;

      var rot = (parseInt($val("spw_rotation","0"),10) * Math.PI)/180;

      ctx.save(); ctx.translate(cx, cy); ctx.rotate(rot);
      ctx.drawImage(logoIm, -drawW/2, -drawH/2, drawW, drawH);
      ctx.restore();
    }

    return canvas.toDataURL("image/png");
  }

  async function postJSON(url, payload){
    try{
      var resp = await fetch(url,{
        method:"POST",
        headers:{ "Content-Type":"application/json", "X-Requested-With":"XMLHttpRequest" },
        credentials:"same-origin",
        body: JSON.stringify(payload),
      });
      var txt = await resp.text();
      var data=null; try{ data = JSON.parse(txt); }catch(_){}
      return {ok: !!(data && (data.ok===true || data.ok==="true")), data:data, status:resp.status, raw:txt};
    }catch(e){ return {ok:false, data:null, status:0, raw:String(e)}; }
  }
  async function postForm(url, payload){
    try{
      var fd = new FormData();
      Object.keys(payload||{}).forEach(function(k){ fd.append(k, payload[k]); });
      var resp = await fetch(url, { method: "POST", body: fd, credentials:"same-origin" });
      var txt = await resp.text();
      var data=null; try{ data = JSON.parse(txt); }catch(_){}
      return {ok: resp.ok && (!!data ? (data.ok===true || data.ok==="true") : true), data:data||{}, status:resp.status, raw:txt};
    }catch(e){ return {ok:false, data:null, status:0, raw:String(e)}; }
  }

  async function addToCart(){
    var variantId=($val("spw_variant_id","")||"").trim();
    var qty=parseInt($val("spw_qty","1"),10)||1;
    var tech=( (document.querySelector("input[name='spw_tech']:checked")||{}).value )||"";
    var svgColor=( (document.querySelector("input[name='spw_svg_color']:checked")||{}).value )||"";
    var notes=($val("spw_notes","")||"").trim();
    if(!variantId){ alert("Falta la variante del producto."); return; }

    var pngB64="";
    try{
      var du = await renderPNGDataURL();
      sessionStorage.setItem('spw_last_product_id', String(variantId));
      sessionStorage.setItem('spw_last_png', du || '');
      sessionStorage.setItem('spw_last_color', svgColor || '');
      pngB64 = du ? du.split('base64,')[1] : "";
    }catch(_){}

    // 1) meta JSON -> fallback HTTP
    var r1 = await postJSON("/spw/add_to_cart_meta", {
      variant_id: parseInt(variantId,10), qty: qty, tech: tech, svg_color: svgColor, notes: notes
    });
    if(!r1.ok){ r1 = await postForm("/spw/add_to_cart_meta_http", {
      variant_id: variantId, qty: qty, tech: tech, svg_color: svgColor, notes: notes
    }); }
    if(!r1.ok){ alert((r1.data && r1.data.message) ? r1.data.message : "No se pudo añadir al carrito."); return; }

    try { if (r1.data && r1.data.line_id) sessionStorage.setItem('spw_last_line_id', String(r1.data.line_id)); } catch(_){}

    // 2) PNG JSON -> fallback HTTP (no bloquea redirección)
    if(pngB64){
      var r2 = await postJSON("/spw/attach_png", { line_id: r1.data.line_id, png_b64: pngB64 });
      if(!r2.ok){ await postForm("/spw/attach_png_http", { line_id: r1.data.line_id, png_b64: pngB64 }); }
    }

    // Redirección con marcador de línea
    var baseUrl = (r1.data && r1.data.cart_url) || "/shop/cart";
    var withParam = (r1.data && r1.data.line_id)
      ? (baseUrl + (baseUrl.indexOf('?')===-1?'?':'&') + 'spw_line_id=' + encodeURIComponent(r1.data.line_id))
      : baseUrl;
    window.location.href = withParam;
  }

  // Descarga iOS/Android/Escritorio (recuperado)
  async function downloadPNGiOSSafe(){
    try{
      var dataUrl = await renderPNGDataURL();
      var a = document.createElement("a");
      a.href = dataUrl; a.download = "personalizacion.png";
      if (typeof a.download === "undefined") {
        window.location.href = dataUrl; // iOS Safari
      } else {
        document.body.appendChild(a); a.click(); a.remove();
      }
    }catch(_){ alert("No se pudo generar el PNG."); }
  }

  function init(){
    var logoInput=document.getElementById("spw_logo_input");
    var logoEl=document.getElementById("spw_logo_preview");
    if(logoInput){
      logoInput.addEventListener("change", async function(ev){
        var f = ev.target.files && ev.target.files[0]; if(!f) return;
        var name=(f.name||"").toLowerCase();
        S.isSVG = name.endsWith(".svg");
        var dataURL = await readAsDataURL(f);
        S.logoDataURL = dataURL;
        logoEl.src = dataURL;
        applyTransform();
      });
    }
    ["spw_size","spw_pos_x","spw_pos_y","spw_rotation"].forEach(function(id){
      var el=document.getElementById(id); if(el) el.addEventListener("input", applyTransform);
    });
    window.spwReset=function(){
      document.getElementById("spw_size").value=100;
      document.getElementById("spw_pos_x").value=0;
      document.getElementById("spw_pos_y").value=10;
      document.getElementById("spw_rotation").value=0;
      applyTransform();
    };

    var dl=document.getElementById("spw_download_png"); if(dl){ dl.addEventListener("click", function(){ downloadPNGiOSSafe(); }); }
    var add=document.getElementById("spw_add_to_cart"); if(add){ add.addEventListener("click", addToCart); }

    applyTransform();
  }

  if(document.readyState==="loading"){ document.addEventListener("DOMContentLoaded", init); } else { init(); }
})();

xpath.script:
(function(){
  "use strict";
  function q(sel, root){return (root||document).querySelector(sel);}
  function qa(sel, root){return Array.from((root||document).querySelectorAll(sel));}

  function getUrlParam(name){
    try{ return new URL(location.href).searchParams.get(name); }catch(_){ return null; }
  }
  function getLineId(line){
    if(!line) return null;

    // 1) atributo directo en contenedores o botones
    var direct = line.getAttribute('data-line-id')
               || (q('[data-line-id]', line) && q('[data-line-id]', line).getAttribute('data-line-id'));
    if (direct) return String(direct);

    // 2) input hidden line_id
    var inp = q('input[name="line_id"]', line) || q('[name="line_id"]', line);
    if (inp && inp.value) return String(inp.value);

    // 3) enlaces/botones con ?line_id=
    var a = q('a[href*="line_id="]', line) || q('form[action*="line_id="]', line);
    if (a){
      try{
        var u = new URL(a.getAttribute('href') || a.getAttribute('action'), location.origin);
        var lid = u.searchParams.get('line_id');
        if (lid) return String(lid);
      }catch(_){}
    }
    return null;
  }

  function findLines(){
    // candidatos típicos de Odoo
    var scope = q('.js_cart_lines') || document;
    var nodes = qa('.o_wsale_cart_item, .js_cart_line, .row.js_cart_line, tr.js_cart_line, .card.js_cart_item, [data-line-id]', scope);
    // filtra sólo contenedores raíz (evita coger un hijo dentro de la misma línea)
    return nodes.filter(function(n){ return !nodes.some(function(m){ return m!==n && m.contains(n); }); });
  }

  function qtyBlock(line){
    return q(".o_wsale_cart_quantity", line)
        || q("div[name='quantity']", line)
        || q(".css_quantity", line)
        || q(".input-group", line)
        || q(".input-group-append", line)
        || null;
  }

  function insertPreview(line, src, lineId, hex){
    // borra previos de esa línea
    qa('.spw-preview[data-line="'+lineId+'"]', line).forEach(function(x){ x.remove(); });

    var wrap = document.createElement("div");
    wrap.className = "spw-preview";
    wrap.setAttribute("data-line", lineId);
    wrap.style.display = "flex";
    wrap.style.alignItems = "center";
    wrap.style.gap = "8px";
    wrap.style.marginTop = "8px";

    var img = new Image();
    img.alt = "Personalización";
    img.loading = "lazy";
    img.src = src;
    img.style.maxWidth = "110px";
    img.style.height = "auto";
    img.style.border = "1px solid #e5e7eb";
    img.style.borderRadius = "6px";
    img.onerror = function(){ wrap.remove(); };

    wrap.appendChild(img);

    if (hex && /^#[0-9A-F]{6}$/i.test(hex)) {
      var sw = document.createElement("span");
      sw.title = hex;
      sw.style.display = "inline-block";
      sw.style.width = "14px";
      sw.style.height = "14px";
      sw.style.borderRadius = "999px";
      sw.style.border = "1px solid #e5e7eb";
      sw.style.background = hex;
      wrap.appendChild(sw);
    }

    var qBlock = qtyBlock(line);
    if (qBlock && qBlock.parentNode){
      qBlock.parentNode.insertBefore(wrap, qBlock.nextSibling); // hermano del bloque de cantidad
    } else {
      line.appendChild(wrap);
    }
  }

  function inject(){
    if (!/\/shop\/cart/.test(location.pathname)) return;

    var wanted = getUrlParam('spw_line_id');
    var lastId=null, lastPng=null, lastColor=null;
    try{
      lastId   = sessionStorage.getItem('spw_last_line_id');
      lastPng  = sessionStorage.getItem('spw_last_png');
      lastColor= sessionStorage.getItem('spw_last_color');
    }catch(_){}

    var lines = findLines();

    // limpia previews huérfanas
    qa(".spw-preview").forEach(function(el){
      var lid = el.getAttribute("data-line");
      var keep = lines.some(function(l){ return getLineId(l) === lid; });
      if(!keep) el.remove();
    });

    lines.forEach(function(line){
      var id = getLineId(line);
      if(!id) return;

      // si venimos de añadir justo ahora
      if (wanted && lastId && wanted === lastId && id === lastId && lastPng){
        insertPreview(line, lastPng, id, lastColor);
        return;
      }

      // fallback estable desde servidor
      var url = "/spw/line_preview/" + encodeURIComponent(id) + ".png?_=" + Date.now();
      insertPreview(line, url, id, null);
    });

    // limpieza de marcadores tras usar
    if (wanted && lastId && wanted === lastId){
      try{
        sessionStorage.removeItem('spw_last_line_id');
        sessionStorage.removeItem('spw_last_png');
        sessionStorage.removeItem('spw_last_color');
      }catch(_){}
    }
  }

  function boot(){
    inject();
    var root = q(".js_cart_lines") || q(".o_wsale_cart") || q("main") || document.body;
    if (window.MutationObserver && root){
      var mo = new MutationObserver(function(){ requestAnimationFrame(inject); });
      mo.observe(root, {childList:true, subtree:true});
    }
    setTimeout(inject, 350);
    setTimeout(inject, 1000);
  }

  if (document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', boot);
  }else{
    boot();
  }
})();
